// SPDX-License-Identifier: Apache-2.0
//! Repository discovery and loading — the I/O half the core crate refuses (§79.1, §79.4).

use std::fmt;
use std::fs;

use camino::{Utf8Path, Utf8PathBuf};
use openwarrant_compiler::{AtomSource, CompilationBasis, SasPin, ScopeSource};
use openwarrant_core::{
    AdrError, AdrRecord, Manifest, RepositoryConfig, ValidatedManifest, frontmatter,
};

use openwarrant_core::authority::{AuthorityRegister, RoleAssignment};
use openwarrant_core::deliverable::Deliverable;
use openwarrant_core::verification::Verification;

use crate::diagnostic::{Diagnostic, Report};
use crate::init::CONFIG_FILE;

#[derive(Debug)]
pub enum RepoError {
    /// A command-level failure that is not about locating or parsing the
    /// repository — an unknown view name, an uncompilable Warrant. Kept
    /// separate from the structured variants so it cannot absorb them.
    Message(String),
    NotFound {
        from: Utf8PathBuf,
    },
    NonUtf8Path,
    Io {
        context: String,
        source: std::io::Error,
    },
    ConfigParse {
        path: Utf8PathBuf,
        source: toml::de::Error,
    },
    ConfigInvalid {
        path: Utf8PathBuf,
        source: openwarrant_core::ConfigError,
    },
    ManifestParse {
        path: Utf8PathBuf,
        source: toml::de::Error,
    },
    UnknownWarrant {
        alias: String,
        known: Vec<String>,
    },
}

impl fmt::Display for RepoError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NotFound { from } => write!(
                f,
                "no {CONFIG_FILE} found in {from} or any parent directory. \
                 Run `war init --namespace <NS>` to create one."
            ),
            Self::Message(m) => write!(f, "{m}"),
            Self::NonUtf8Path => write!(f, "the current directory is not valid UTF-8"),
            Self::Io { context, source } => write!(f, "{context}: {source}"),
            Self::ConfigParse { path, source } => write!(f, "{path}: {source}"),
            Self::ConfigInvalid { path, source } => write!(f, "{path}: {source}"),
            Self::ManifestParse { path, source } => write!(f, "{path}: {source}"),
            Self::UnknownWarrant { alias, known } => write!(
                f,
                "no Warrant {alias:?} in this repository. Known: {}",
                if known.is_empty() {
                    "(none)".to_owned()
                } else {
                    known.join(", ")
                }
            ),
        }
    }
}

impl std::error::Error for RepoError {}

/// An initialized OpenWarrant repository.
#[derive(Debug, Clone)]
pub struct Repository {
    pub root: Utf8PathBuf,
    pub config: RepositoryConfig,
}

impl Repository {
    /// Find the nearest ancestor containing `openwarrant.toml`.
    pub fn discover(start: Option<Utf8PathBuf>) -> Result<Self, RepoError> {
        let start = match start {
            Some(path) => path,
            None => {
                let cwd = std::env::current_dir().map_err(|source| RepoError::Io {
                    context: "could not read the current directory".to_owned(),
                    source,
                })?;
                Utf8PathBuf::from_path_buf(cwd).map_err(|_| RepoError::NonUtf8Path)?
            }
        };

        let mut cursor: &Utf8Path = &start;
        loop {
            let candidate = cursor.join(CONFIG_FILE);
            if candidate.is_file() {
                return Self::open(cursor.to_owned());
            }
            match cursor.parent() {
                Some(parent) => cursor = parent,
                None => return Err(RepoError::NotFound { from: start }),
            }
        }
    }

    /// Open a repository whose root is already known.
    pub fn open(root: Utf8PathBuf) -> Result<Self, RepoError> {
        let path = root.join(CONFIG_FILE);
        let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
            context: format!("could not read {path}"),
            source,
        })?;
        let config: RepositoryConfig =
            toml::from_str(&text).map_err(|source| RepoError::ConfigParse {
                path: path.clone(),
                source,
            })?;
        config
            .validate()
            .map_err(|source| RepoError::ConfigInvalid { path, source })?;
        Ok(Self { root, config })
    }

    /// The configured warrants directory.
    #[must_use]
    pub fn warrants_dir(&self) -> Utf8PathBuf {
        self.root.join(&self.config.paths.warrants)
    }

    /// The actor this tool acts as when it performs work (§27.1).
    ///
    /// `[project] performer` in `openwarrant.toml`, default `claude`, and
    /// deliberately not configurable from the command line. The performer
    /// identity is what every self-* check compares against —
    /// self-verification (§46), self-authorization (§27.2), self-resolution
    /// (§27.3 condition 4). A flag that let the caller rename the performer
    /// would let it walk out of all three by claiming to be somebody else;
    /// a committed, human-written file cannot be reached that way.
    #[must_use]
    pub fn performer(&self) -> String {
        self.config
            .project
            .performer
            .clone()
            .unwrap_or_else(|| "claude".to_owned())
    }

    /// Role assignments in force for this repository (§27.4).
    ///
    /// `docs/authority/roles.toml` is authored by a human and by nothing else.
    /// There is no `war authority grant`: a command that could write this file
    /// would let an agent assign itself the roles §27.2 exists to withhold, so
    /// the register is read-only to every tool in this workspace.
    ///
    /// An absent file yields an empty register, and an empty register grants
    /// nobody anything — the fail-closed direction.
    pub fn load_authority_register(&self) -> Result<AuthorityRegister, RepoError> {
        let path = self.root.join("docs/authority/roles.toml");
        if !path.is_file() {
            return Ok(AuthorityRegister::default());
        }
        let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
            context: format!("could not read {path}"),
            source,
        })?;

        #[derive(serde::Deserialize)]
        struct File {
            #[serde(default)]
            assignment: Vec<RoleAssignment>,
        }

        let file: File = toml::from_str(&text)
            .map_err(|e| RepoError::Message(format!("could not parse {path}: {e}")))?;

        // A malformed assignment is refused for the whole file rather than
        // skipped. Skipping would silently drop authority, and an actor whose
        // grant quietly vanished reads identically to one that never had it.
        for assignment in &file.assignment {
            assignment
                .validate()
                .map_err(|e| RepoError::Message(format!("{path}: {e}")))?;
        }
        Ok(AuthorityRegister::new(file.assignment))
    }

    /// The persisted authorization for one Warrant (§28.4), if any.
    ///
    /// A malformed record is an error, never an absent one: "this Warrant was
    /// never authorized" and "its authorization would not parse" must not
    /// report identically, because only one of them is safe to work around.
    pub fn load_authorization(
        &self,
        dir: &Utf8Path,
    ) -> Result<Option<crate::authorize::AuthorizationRecord>, RepoError> {
        let path = dir.join("authorization.toml");
        if !path.is_file() {
            return Ok(None);
        }
        let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
            context: format!("could not read {path}"),
            source,
        })?;
        toml::from_str(&text)
            .map(Some)
            .map_err(|e| RepoError::Message(format!("could not parse {path}: {e}")))
    }

    /// Judgments recorded for one Warrant (§42).
    /// The §56.2 record, if one has been ingested (`war resolve --response`).
    pub fn load_resolution(
        &self,
        dir: &Utf8Path,
    ) -> Result<Option<crate::resolution_cmd::ResolutionRecord>, RepoError> {
        let path = dir.join("resolution.toml");
        if !path.is_file() {
            return Ok(None);
        }
        let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
            context: format!("could not read {path}"),
            source,
        })?;
        toml::from_str(&text)
            .map(Some)
            .map_err(|e| RepoError::Message(format!("could not parse {path}: {e}")))
    }

    pub fn load_judgments(
        &self,
        dir: &Utf8Path,
    ) -> Result<Vec<openwarrant_core::Judgment>, RepoError> {
        let path = dir.join("judgments.toml");
        if !path.is_file() {
            return Ok(vec![]);
        }
        let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
            context: format!("could not read {path}"),
            source,
        })?;
        toml::from_str::<crate::authorize::JudgmentRecord>(&text)
            .map(|r| r.judgment)
            .map_err(|e| RepoError::Message(format!("could not parse {path}: {e}")))
    }

    /// Assumptions declared for one Warrant (§36), if the sidecar exists.
    ///
    /// `Ok(None)` means no `rationale.toml` — the question was never asked.
    /// `Ok(Some(vec![]))` means it was asked and the answer was none. The
    /// resolver treats those differently and would be unsound if it could not
    /// tell them apart (Law 15: Unknown is neither failure nor pass).
    pub fn load_rationale(
        &self,
        dir: &Utf8Path,
    ) -> Result<Option<Vec<openwarrant_core::rationale::Assumption>>, RepoError> {
        let path = dir.join("rationale.toml");
        if !path.is_file() {
            return Ok(None);
        }
        let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
            context: format!("could not read {path}"),
            source,
        })?;

        #[derive(serde::Deserialize)]
        struct File {
            #[serde(default)]
            assumption: Vec<openwarrant_core::rationale::Assumption>,
        }

        let file: File = toml::from_str(&text)
            .map_err(|e| RepoError::Message(format!("could not parse {path}: {e}")))?;
        for assumption in &file.assumption {
            assumption
                .validate()
                .map_err(|e| RepoError::Message(format!("{path}: {} — {e}", assumption.id)))?;
        }
        Ok(Some(file.assumption))
    }

    /// Every Warrant directory, sorted by name.
    ///
    /// A directory is a Warrant because it contains a `manifest.toml`, not
    /// because of what it is called — §59: "Semantics are not inferred from
    /// paths alone."
    pub fn warrant_dirs(&self) -> Result<Vec<Utf8PathBuf>, RepoError> {
        let dir = self.warrants_dir();
        if !dir.is_dir() {
            return Ok(vec![]);
        }
        let mut out = Vec::new();
        let entries = fs::read_dir(&dir).map_err(|source| RepoError::Io {
            context: format!("could not read {dir}"),
            source,
        })?;
        for entry in entries {
            let entry = entry.map_err(|source| RepoError::Io {
                context: format!("could not read an entry in {dir}"),
                source,
            })?;
            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
                continue;
            };
            if path.join("manifest.toml").is_file() {
                out.push(path);
            }
        }
        out.sort();
        Ok(out)
    }

    /// Resolve a Warrant directory by local alias.
    pub fn warrant_dir(&self, alias: &str) -> Result<Utf8PathBuf, RepoError> {
        let dirs = self.warrant_dirs()?;
        for dir in &dirs {
            if dir.file_name() == Some(alias) {
                return Ok(dir.clone());
            }
        }
        Err(RepoError::UnknownWarrant {
            alias: alias.to_owned(),
            known: dirs
                .iter()
                .filter_map(|d| d.file_name().map(str::to_owned))
                .collect(),
        })
    }

    /// Load one Warrant into a Compilation Basis.
    ///
    /// Reads the manifest, validates it, then reads every declared atom's exact
    /// bytes. Missing atoms and unreadable frontmatter become diagnostics rather
    /// than hard failures, so `war check` can report EVERY problem in one run
    /// instead of stopping at the first — a checker that stops early makes the
    /// author re-run it once per defect.
    pub fn load_warrant(&self, dir: &Utf8Path) -> Result<Loaded, RepoError> {
        let manifest_path = dir.join("manifest.toml");
        let manifest_bytes = fs::read(&manifest_path).map_err(|source| RepoError::Io {
            context: format!("could not read {manifest_path}"),
            source,
        })?;
        let manifest_text = String::from_utf8_lossy(&manifest_bytes).into_owned();
        let manifest: Manifest =
            toml::from_str(&manifest_text).map_err(|source| RepoError::ManifestParse {
                path: manifest_path.clone(),
                source,
            })?;

        let mut report = Report::default();
        let relative_manifest = self.relative(&manifest_path);

        let validated = match manifest.validate(Some(self.config.project.namespace.as_str())) {
            Ok(v) => v,
            Err(source) => {
                report.push(Diagnostic::error(
                    "manifest.invalid",
                    relative_manifest.clone(),
                    source.to_string(),
                ));
                return Ok(Loaded {
                    dir: dir.to_owned(),
                    basis: None,
                    validated: None,
                    report,
                });
            }
        };

        let mut atoms = Vec::new();
        for entry in &manifest.atoms {
            let Some(rel) = entry.path.as_deref() else {
                // A `ref =` atom is bound to an authority we cannot resolve
                // offline. Not an error and not a pass (Law 15).
                report.push(Diagnostic::unknown(
                    "atom.bound-unresolvable",
                    relative_manifest.clone(),
                    format!(
                        "atom at ordinal {} is bound by `ref` and cannot be resolved \
                         offline; federation is not implemented",
                        entry.ordinal
                    ),
                ));
                continue;
            };

            let path = dir.join(rel);
            let bytes = match fs::read(&path) {
                Ok(bytes) => bytes,
                Err(source) => {
                    report.push(Diagnostic::error(
                        "atom.missing",
                        self.relative(&path),
                        format!("declared at ordinal {}: {source}", entry.ordinal),
                    ));
                    continue;
                }
            };

            // Jurisdiction comes from the atom's own frontmatter when it has
            // one; a `.yaml` structured atom (§62.1) has none, and that is not
            // a defect.
            let text = String::from_utf8_lossy(&bytes);
            let jurisdiction = match frontmatter::parse(&text) {
                Ok(fm) => fm.scalar("jurisdiction").unwrap_or("authored").to_owned(),
                Err(err) => {
                    if rel.ends_with(".md") {
                        report.push(Diagnostic::error(
                            "atom.frontmatter",
                            self.relative(&path),
                            err.to_string(),
                        ));
                    }
                    "authored".to_owned()
                }
            };

            atoms.push(AtomSource {
                ordinal: entry.ordinal,
                role: entry.role.clone(),
                jurisdiction,
                source: rel.to_owned(),
                bytes,
                required: entry.required,
            });
        }

        let scope_path = dir.join("scope.toml");
        let scope = if scope_path.is_file() {
            match fs::read(&scope_path) {
                Ok(bytes) => Some(ScopeSource {
                    source: self.relative(&scope_path),
                    bytes,
                }),
                Err(source) => {
                    report.push(Diagnostic::error(
                        "scope.unreadable",
                        self.relative(&scope_path),
                        source.to_string(),
                    ));
                    None
                }
            }
        } else {
            None
        };

        Ok(Loaded {
            dir: dir.to_owned(),
            basis: Some(CompilationBasis {
                manifest,
                manifest_source: relative_manifest,
                manifest_bytes,
                atoms,
                scope,
                // §14 — the SAS revision is a Basis input. An AUTHORIZED Warrant
                // compiles against the revision its authorization recorded, so
                // a later SAS revision cannot move its contract digest out from
                // under the signature; an unauthorized one follows the latest
                // recorded revision. Absent until any revision is recorded.
                sas: self.sas_pin_for(dir)?,
            }),
            validated: Some(validated),
            report,
        })
    }

    /// The configured ADR atoms directory.
    #[must_use]
    pub fn adr_atoms_dir(&self) -> Utf8PathBuf {
        self.root.join(&self.config.paths.adrs).join("atoms")
    }

    /// Where the generated Warrant Overview is written (§17.5 `status`).
    #[must_use]
    pub fn warrant_overview_path(&self) -> Utf8PathBuf {
        self.root
            .join(&self.config.paths.warrants)
            .join("generated")
            .join("WARRANT_OVERVIEW.md")
    }

    /// The SAS document: exactly one Markdown file under the configured path.
    ///
    /// Zero is an error and so is two. A repository with two candidate
    /// documents has no single thing to pin, and guessing which one is
    /// normative is the failure §101.6 exists to prevent.
    pub fn sas_document(&self) -> Result<(Utf8PathBuf, Vec<u8>), RepoError> {
        let dir = self.root.join(&self.config.paths.sas);
        let mut docs: Vec<Utf8PathBuf> = fs::read_dir(&dir)
            .map_err(|source| RepoError::Io {
                context: format!("could not read {dir}"),
                source,
            })?
            .filter_map(Result::ok)
            .filter_map(|e| Utf8PathBuf::from_path_buf(e.path()).ok())
            .filter(|p| p.extension() == Some("md"))
            .collect();
        docs.sort();
        match docs.as_slice() {
            [one] => {
                let bytes = fs::read(one).map_err(|source| RepoError::Io {
                    context: format!("could not read {one}"),
                    source,
                })?;
                Ok((one.clone(), bytes))
            }
            [] => Err(RepoError::Message(format!(
                "no SAS document (*.md) under {dir}"
            ))),
            many => Err(RepoError::Message(format!(
                "{} SAS documents under {dir}; there must be exactly one to pin: {}",
                many.len(),
                many.iter()
                    .map(|p| self.relative(p))
                    .collect::<Vec<_>>()
                    .join(", ")
            ))),
        }
    }

    /// Main-document projection input. Legacy proposal still reads `sas_document`.
    pub fn selected_sas_document(&self) -> Result<(Utf8PathBuf, Vec<u8>), RepoError> {
        if let Some(record) = self.latest_sas_revision()?
            && record.source_set.is_some()
        {
            return crate::sas_source_set::captured_main(self, &record);
        }
        self.sas_document()
    }

    #[must_use]
    pub fn sas_revisions_dir(&self) -> Utf8PathBuf {
        self.root.join(&self.config.paths.sas).join("revisions")
    }

    #[must_use]
    pub fn sas_revision_path(&self, version: &str) -> Utf8PathBuf {
        self.sas_revisions_dir().join(format!("{version}.toml"))
    }

    /// Every SAS revision on record (§101), validated. A malformed record is an
    /// error for the set: an accepted revision that quietly failed to load
    /// would read as "the document is unpinned", which is the wrong direction.
    pub fn load_sas_revisions(&self) -> Result<Vec<openwarrant_core::SasRevision>, RepoError> {
        let dir = self.sas_revisions_dir();
        if !dir.is_dir() {
            return Ok(vec![]);
        }
        let mut paths: Vec<Utf8PathBuf> = fs::read_dir(&dir)
            .map_err(|source| RepoError::Io {
                context: format!("could not read {dir}"),
                source,
            })?
            .filter_map(Result::ok)
            .filter_map(|e| Utf8PathBuf::from_path_buf(e.path()).ok())
            .filter(|p| p.extension() == Some("toml"))
            .collect();
        paths.sort();
        let mut out = Vec::new();
        for path in paths {
            let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
                context: format!("could not read {path}"),
                source,
            })?;
            let r: openwarrant_core::SasRevision = toml::from_str(&text)
                .map_err(|e| RepoError::Message(format!("could not parse {path}: {e}")))?;
            r.validate()
                .map_err(|e| RepoError::Message(format!("{path}: {e}")))?;
            out.push(r);
        }
        Ok(out)
    }

    /// The revision the document is held to: newest accepted, else newest
    /// proposed, else none.
    /// The SAS revision this Warrant compiles against (see `load_warrant`).
    ///
    /// An authorization naming a revision that has no record is an error
    /// surfaced by `war check` as `sas.pin-unknown`; here it falls back to the
    /// latest so the Warrant still compiles and the check can name the fault.
    pub fn sas_pin_for(&self, dir: &Utf8Path) -> Result<Option<SasPin>, RepoError> {
        let all = self.load_sas_revisions()?;
        // OW-ADR-0016: the latest amendment that names a `sas_revision` re-pins
        // the Warrant ahead of its authorization, so the contract digest moves
        // and a new authorization revision is what `war sign --list` shows.
        // A named revision with no record falls through to the authorization's
        // pin; `war check` reports it as `sas.pin-unknown`.
        let amended = amendment_sas_revision(dir)
            .and_then(|(v, _)| all.iter().find(|r| r.version == v).cloned());
        let pinned = match amended {
            Some(r) => Some(r),
            None => self
                .load_authorization(dir)
                .ok()
                .flatten()
                .and_then(|a| a.sas_revision)
                .and_then(|v| all.iter().find(|r| r.version == v).cloned()),
        };
        let chosen = match pinned {
            Some(r) => Some(r),
            None => crate::sas::pin_of(&all).cloned(),
        };
        if let Some(r) = &chosen
            && r.source_set.is_some()
        {
            crate::sas_source_set::validate(self, r, false)?;
        }
        Ok(chosen.map(|r| SasPin {
            version: r.version,
            sha256: r.sha256,
        }))
    }

    pub fn latest_sas_revision(&self) -> Result<Option<openwarrant_core::SasRevision>, RepoError> {
        let all = self.load_sas_revisions()?;
        Ok(crate::sas::pin_of(&all).cloned())
    }

    /// Where the corpus projection is written (§17.5 `status`, corpus form).
    ///
    /// Two files from one build: the Markdown a person reads and the canonical
    /// JSON an agent reads. Named `CORPUS_STATUS` rather than `STATUS` because
    /// `status` is already the per-Warrant §17.5 view name.
    #[must_use]
    pub fn corpus_status_md_path(&self) -> Utf8PathBuf {
        self.root
            .join(&self.config.paths.warrants)
            .join("generated")
            .join("CORPUS_STATUS.md")
    }

    #[must_use]
    pub fn corpus_status_html_path(&self) -> Utf8PathBuf {
        self.root
            .join(&self.config.paths.warrants)
            .join("generated")
            .join("CORPUS_STATUS.html")
    }

    #[must_use]
    pub fn corpus_status_json_path(&self) -> Utf8PathBuf {
        self.root
            .join(&self.config.paths.warrants)
            .join("generated")
            .join("CORPUS_STATUS.json")
    }

    /// Where the generated ADR Overview is written (§19.6).
    #[must_use]
    pub fn adr_overview_path(&self) -> Utf8PathBuf {
        self.root
            .join(&self.config.paths.adrs)
            .join("generated")
            .join("ADR_OVERVIEW.md")
    }

    /// Load every ADR atom, plus whatever failed to parse.
    ///
    /// Returns parse failures rather than aborting, so `war check` reports every
    /// malformed ADR in one run instead of one per invocation.
    pub fn load_adrs(&self) -> Result<AdrCorpus, RepoError> {
        let dir = self.adr_atoms_dir();
        if !dir.is_dir() {
            return Ok(AdrCorpus::default());
        }
        let mut paths = Vec::new();
        for entry in fs::read_dir(&dir).map_err(|source| RepoError::Io {
            context: format!("could not read {dir}"),
            source,
        })? {
            let entry = entry.map_err(|source| RepoError::Io {
                context: format!("could not read an entry in {dir}"),
                source,
            })?;
            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
                continue;
            };
            if path.extension() == Some("md") {
                paths.push(path);
            }
        }
        // Deterministic order: the overview must not depend on readdir order.
        paths.sort();

        let mut records = Vec::new();
        let mut failures = Vec::new();
        for path in paths {
            let relative = self.relative(&path);
            let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
                context: format!("could not read {path}"),
                source,
            })?;
            match AdrRecord::parse(&relative, &text) {
                Ok(record) => records.push(record),
                Err(err) => failures.push((relative, err)),
            }
        }
        Ok(AdrCorpus { records, failures })
    }

    /// Verification records for one Warrant (§46, §38.5).
    ///
    /// Each `verifications/*.toml` is one obligation verified by one verifier.
    /// A missing directory is not an error — it means nothing has been verified,
    /// which is a true and common state, distinct from a verification that
    /// failed to parse.
    pub fn load_verifications(&self, dir: &Utf8Path) -> Result<VerificationSet, RepoError> {
        let vdir = dir.join("verifications");
        if !vdir.is_dir() {
            return Ok(VerificationSet::default());
        }
        let mut paths = Vec::new();
        for entry in fs::read_dir(&vdir).map_err(|source| RepoError::Io {
            context: format!("could not read {vdir}"),
            source,
        })? {
            let entry = entry.map_err(|source| RepoError::Io {
                context: format!("could not read an entry in {vdir}"),
                source,
            })?;
            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
                continue;
            };
            if path.extension() == Some("toml") {
                paths.push(path);
            }
        }
        paths.sort();

        let mut records = Vec::new();
        let mut failures = Vec::new();
        for path in paths {
            let relative = self.relative(&path);
            let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
                context: format!("could not read {path}"),
                source,
            })?;
            match toml::from_str::<Verification>(&text) {
                Ok(v) => records.push(v),
                Err(e) => failures.push((relative, e.to_string())),
            }
        }
        Ok(VerificationSet { records, failures })
    }

    /// Corrections on file for one Warrant (OW-WAR-0064): every
    /// `corrections/*.toml`, sorted by path, parse failures kept beside the
    /// records so a malformed correction is reported rather than skipped.
    pub fn load_corrections(&self, dir: &Utf8Path) -> Result<CorrectionSet, RepoError> {
        let cdir = dir.join("corrections");
        if !cdir.is_dir() {
            return Ok(CorrectionSet::default());
        }
        let mut paths = Vec::new();
        for entry in fs::read_dir(&cdir).map_err(|source| RepoError::Io {
            context: format!("could not read {cdir}"),
            source,
        })? {
            let entry = entry.map_err(|source| RepoError::Io {
                context: format!("could not read an entry in {cdir}"),
                source,
            })?;
            let Ok(path) = Utf8PathBuf::from_path_buf(entry.path()) else {
                continue;
            };
            if path.extension() == Some("toml") {
                paths.push(path);
            }
        }
        paths.sort();
        let mut records = Vec::new();
        let mut failures = Vec::new();
        for path in paths {
            let relative = self.relative(&path);
            let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
                context: format!("could not read {path}"),
                source,
            })?;
            match toml::from_str::<openwarrant_core::correction::CorrectionRecord>(&text) {
                Ok(r) => records.push((relative, r)),
                Err(e) => failures.push((relative, e.to_string())),
            }
        }
        Ok(CorrectionSet { records, failures })
    }

    /// Deliverables declared for one Warrant (§37).
    ///
    /// A single `deliverables.toml` rather than a directory: a Warrant declares a
    /// handful, they are read together, and one file keeps them reviewable as a
    /// set.
    pub fn load_deliverables(&self, dir: &Utf8Path) -> Result<DeliverableSet, RepoError> {
        let path = dir.join("deliverables.toml");
        if !path.is_file() {
            return Ok(DeliverableSet::default());
        }
        let text = fs::read_to_string(&path).map_err(|source| RepoError::Io {
            context: format!("could not read {path}"),
            source,
        })?;

        #[derive(serde::Deserialize)]
        struct File {
            #[serde(default)]
            deliverable: Vec<Deliverable>,
        }

        match toml::from_str::<File>(&text) {
            Ok(f) => Ok(DeliverableSet {
                records: f.deliverable,
                failures: vec![],
            }),
            Err(e) => Ok(DeliverableSet {
                records: vec![],
                failures: vec![(self.relative(&path), e.to_string())],
            }),
        }
    }

    /// A repository-relative path, for diagnostics and for the IR.
    ///
    /// Absolute paths must never reach the IR: they would make a digest depend
    /// on where the repository happens to be checked out.
    #[must_use]
    pub fn relative(&self, path: &Utf8Path) -> String {
        path.strip_prefix(&self.root)
            .unwrap_or(path)
            .as_str()
            .to_owned()
    }
}

/// The ADR corpus as read from disk.
///
/// Parse failures travel alongside the records rather than replacing them: one
/// malformed ADR must not hide the other twenty, and `war check` reports every
/// problem in a single run.
#[derive(Debug, Default)]
pub struct AdrCorpus {
    pub records: Vec<AdrRecord>,
    /// `(repository-relative path, why it would not parse)`.
    pub failures: Vec<(String, AdrError)>,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// Deliverables for one Warrant, and a parse failure if the file would not read.
///
/// A malformed `deliverables.toml` yields NO records and a recorded failure,
/// never silently zero deliverables — "the file is broken" and "this Warrant
/// declares none" are different states and must not report identically.
#[derive(Debug, Default)]
pub struct DeliverableSet {
    pub records: Vec<Deliverable>,
    pub failures: Vec<(String, String)>,
}

/// Verification records for one Warrant, and the ones that would not parse.
///
/// Failures travel alongside the records for the same reason `AdrCorpus` does:
/// an unreadable verification is not an absent one, and silently treating it as
/// absent would turn a malformed record into "nothing was verified" — which
/// reads identically to the honest state and is not.
#[derive(Debug, Default)]
pub struct VerificationSet {
    pub records: Vec<Verification>,
    /// `(repository-relative path, why it would not parse)`.
    pub failures: Vec<(String, String)>,
}

/// Corrections on file for one Warrant (OW-WAR-0064), each with the
/// repository-relative path it was read from — the path is what `war check`
/// digests against the journal's `record_digest`.
#[derive(Debug, Default)]
pub struct CorrectionSet {
    pub records: Vec<(String, openwarrant_core::correction::CorrectionRecord)>,
    /// `(repository-relative path, why it would not parse)`.
    pub failures: Vec<(String, String)>,
}

impl CorrectionSet {
    /// The corrections for one deliverable, in file order.
    pub fn for_deliverable(&self, id: &str) -> Vec<openwarrant_core::correction::Correction> {
        self.records
            .iter()
            .filter(|(_, r)| r.correction.deliverable_id == id)
            .map(|(_, r)| r.correction.clone())
            .collect()
    }
}

/// A Warrant read from disk, with whatever went wrong while reading it.
#[derive(Debug, Clone)]
pub struct Loaded {
    pub dir: Utf8PathBuf,
    /// `None` when the manifest itself was invalid, so nothing downstream can
    /// be trusted.
    pub basis: Option<CompilationBasis>,
    pub validated: Option<ValidatedManifest>,
    pub report: Report,
}

impl Loaded {
    /// The local alias, taken from the directory name when the manifest could
    /// not be validated.
    #[must_use]
    pub fn alias(&self) -> String {
        self.validated
            .as_ref()
            .map(|v| v.alias.to_string())
            .or_else(|| self.dir.file_name().map(str::to_owned))
            .unwrap_or_else(|| self.dir.to_string())
    }
}

/// The `sas_revision` the latest amendment under `amendments/` names, with the
/// file that names it (OW-ADR-0016). Read from the file, not the record
/// struct: the struct is pinned by a resolved Warrant, and the pin is one
/// top-level scalar on the side. "Latest" is by amendment number (`AM-<n>`),
/// then name, so `AM-1000` follows `AM-901`. Only an unindented
/// `sas_revision:` line counts — a key nested under `semantic_diff:` is not
/// the pin.
#[must_use]
pub fn amendment_sas_revision(dir: &Utf8Path) -> Option<(String, Utf8PathBuf)> {
    let mut files: Vec<Utf8PathBuf> = std::fs::read_dir(dir.join("amendments"))
        .ok()?
        .filter_map(Result::ok)
        .filter_map(|e| Utf8PathBuf::from_path_buf(e.path()).ok())
        .filter(|p| p.extension() == Some("yaml"))
        .collect();
    let number = |p: &Utf8Path| -> u64 {
        p.file_stem()
            .and_then(|s| s.rsplit_once('-'))
            .and_then(|(_, n)| n.parse().ok())
            .unwrap_or(0)
    };
    files.sort_by(|a, b| number(a).cmp(&number(b)).then_with(|| a.cmp(b)));
    files.into_iter().rev().find_map(|path| {
        let text = std::fs::read_to_string(&path).ok()?;
        let version = text.lines().find_map(|line| {
            let v = line
                .strip_prefix("sas_revision:")?
                .trim()
                .trim_matches('"')
                .trim();
            (!v.is_empty()).then(|| v.to_owned())
        })?;
        Some((version, path))
    })
}

// SPDX-License-Identifier: Apache-2.0
//! `war sas` — the SAS as a controlled document (SAS §101; §34.1–§34.4).
//!
//! # Two halves, again
//!
//! `war sas propose <version>` writes a proposed revision: the document's
//! digest, a §106 snapshot, the diff against its predecessor. `war sas accept
//! <version>` emits a request; `--response <file>` ingests a human's
//! acceptance through the authority register, which refuses every agent
//! regardless of what the response claims. The split is the one `war
//! authorize` uses and exists for the same reason: an agent may propose a
//! revision of the document that governs it, and may not accept one.
//!
//! # What a refused acceptance writes
//!
//! Nothing. A rejected acceptance must not become a file that later reads as
//! an accepted revision.

use std::fs;

use camino::Utf8Path;
use openwarrant_compiler::sha256_hex;
use openwarrant_core::authority::ActorRole;
use openwarrant_core::sas::{
    SasAcceptance, SasRevision, SasRevisionState, Section106Diff, section_106,
};
use serde::{Deserialize, Serialize};

use crate::diagnostic::{Diagnostic, Report};
use crate::repo::{RepoError, Repository};

pub const ACCEPT_REQUEST_SCHEMA: &str = "oh.war/sas-acceptance-request/v1";
pub const ACCEPT_RESPONSE_SCHEMA: &str = "oh.war/sas-acceptance-response/v1";
pub const ACCEPT_REQUEST_V2_SCHEMA: &str = "oh.war/sas-acceptance-request/v2";
pub const ACCEPT_RESPONSE_V2_SCHEMA: &str = "oh.war/sas-acceptance-response/v2";

/// Propose the document as it stands, as `version`.
pub fn propose(repo: &Repository, version: &str) -> Result<Report, RepoError> {
    let mut report = Report::default();
    let (path, bytes) = repo.sas_document()?;
    let sha256 = sha256_hex(&bytes);
    let text = String::from_utf8_lossy(&bytes);
    let requirements = section_106(&text);
    if requirements.is_empty() {
        return Err(RepoError::Message(format!(
            "{path}: §106 could not be read — no `| <PREFIX>-SAS-RQ-NNN | … |` rows"
        )));
    }

    let existing = repo.load_sas_revisions()?;
    if existing.iter().any(|r| r.version == version) {
        return Err(RepoError::Message(format!(
            "a revision named {version:?} already exists; a revision is proposed once"
        )));
    }
    let predecessor = repo.latest_sas_revision()?;
    let (pred_version, architecture_changing) = match &predecessor {
        Some(p) => {
            let d = Section106Diff::between(&p.requirements, &requirements);
            d.check_stability()
                .map_err(|e| RepoError::Message(e.to_string()))?;
            report.push(Diagnostic::pass(
                "sas.diff",
                format!("§106 against {}: {}", p.version, d.summary()),
            ));
            (Some(p.version.clone()), d.is_architecture_changing())
        }
        None => (None, false),
    };

    let record = SasRevision::proposed(
        version,
        repo.relative(&path),
        sha256.clone(),
        pred_version,
        requirements,
        architecture_changing,
    );
    record
        .validate()
        .map_err(|e| RepoError::Message(e.to_string()))?;
    let out = repo.sas_revision_path(version);
    if let Some(parent) = out.parent() {
        fs::create_dir_all(parent).map_err(|source| RepoError::Io {
            context: format!("could not create {parent}"),
            source,
        })?;
    }
    write_toml(&out, &record)?;
    report.push(Diagnostic::pass(
        "sas.proposed",
        format!(
            "{version} proposed at sha256:{sha256} ({} requirements in §106; architecture-changing: {}) → {}",
            record.requirements.len(),
            architecture_changing,
            repo.relative(&out)
        ),
    ));
    report.note(
        "Proposed, not accepted. §101.2's accepted revision needs a human: `war sas accept <version>` \
         emits the request, `--response <file>` ingests the signature."
            .to_owned(),
    );
    Ok(report)
}

/// What is put to the acceptor.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct AcceptRequest {
    pub schema: String,
    pub version: String,
    pub source: String,
    pub sha256: String,
    pub predecessor: Option<String>,
    pub architecture_changing: bool,
    /// Whether §101.3 requires an `adr_ref` in the response.
    pub adr_required: bool,
    pub diff: Section106Diff,
    pub requirement_count: usize,
    pub eligible_acceptors: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_set: Option<openwarrant_core::sas::SasSourceSetSubject>,
}

/// What the acceptor returns.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct AcceptResponse {
    pub schema: String,
    pub version: String,
    /// Must equal the record's AND the document's current digest.
    pub sha256: String,
    pub accepted_by: String,
    pub acting_role: String,
    pub meaning: String,
    pub effective_time: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub adr_ref: Option<String>,
}

pub fn accept_request(repo: &Repository, version: &str) -> Result<AcceptRequest, RepoError> {
    let record = find(repo, version)?;
    if record.source_set.is_some() {
        crate::sas_source_set::validate(repo, &record, true)?;
    }
    let predecessor = record
        .predecessor
        .as_deref()
        .map(|v| find(repo, v))
        .transpose()?;
    // Record against record, not against the document on disk: the request is
    // about the PROPOSAL as recorded, and ingestion separately refuses to accept
    // it if the bytes have since moved (the stale-digest check). Diffing against
    // disk here would describe a document nobody has proposed.
    let diff = predecessor
        .as_ref()
        .map(|p| Section106Diff::between(&p.requirements, &record.requirements))
        .unwrap_or_default();
    let register = repo.load_authority_register()?;
    Ok(AcceptRequest {
        schema: if record.source_set.is_some() {
            ACCEPT_REQUEST_V2_SCHEMA
        } else {
            ACCEPT_REQUEST_SCHEMA
        }
        .to_owned(),
        version: record.version.clone(),
        source: record.source.clone(),
        sha256: record.sha256.clone(),
        predecessor: record.predecessor.clone(),
        architecture_changing: record.architecture_changing,
        adr_required: record.architecture_changing || record.source_set.is_some(),
        diff,
        requirement_count: record.requirements.len(),
        eligible_acceptors: register
            .holders(ActorRole::Authorizer)
            .filter(|a| a.may_authorize(&repo.performer()).is_ok())
            .map(|a| a.actor.clone())
            .collect(),
        source_set: record.source_set.clone(),
    })
}

pub fn accept_ingest(
    repo: &Repository,
    version: &str,
    response_path: &Utf8Path,
) -> Result<Report, RepoError> {
    accept_inner(repo, version, response_path, None)
}

/// Called only after `war sign` obtains a real terminal confirmation.
pub(crate) fn accept_from_terminal(
    repo: &Repository,
    version: &str,
    response_path: &Utf8Path,
    actor: &str,
) -> Result<Report, RepoError> {
    accept_inner(repo, version, response_path, Some(actor))
}

fn accept_inner(
    repo: &Repository,
    version: &str,
    response_path: &Utf8Path,
    terminal_actor: Option<&str>,
) -> Result<Report, RepoError> {
    let mut report = Report::default();
    let initial = find(repo, version)?;
    let _lock = if initial.source_set.is_some() {
        Some(crate::sas_source_set::lock(repo, version)?)
    } else {
        None
    };
    let record = if _lock.is_some() {
        find(repo, version)?
    } else {
        initial
    };
    let text = fs::read_to_string(response_path).map_err(|source| RepoError::Io {
        context: format!("could not read {response_path}"),
        source,
    })?;
    let response: AcceptResponse = match toml::from_str(&text) {
        Ok(r) => r,
        Err(e) => {
            report.push(Diagnostic::error(
                "sas.response-malformed",
                response_path.to_string(),
                e.to_string(),
            ));
            return Ok(report);
        }
    };
    let refuse = |report: &mut Report, rule: &str, why: String| {
        report.push(Diagnostic::error(rule, response_path.to_string(), why));
    };
    let expected_schema = if record.source_set.is_some() {
        ACCEPT_RESPONSE_V2_SCHEMA
    } else {
        ACCEPT_RESPONSE_SCHEMA
    };
    if response.schema != expected_schema {
        refuse(
            &mut report,
            "sas.response-schema",
            format!("unknown schema {:?}", response.schema),
        );
        return Ok(report);
    }
    if response.version != version {
        refuse(
            &mut report,
            "sas.response-version",
            format!("response names {:?}, ingesting {version}", response.version),
        );
        return Ok(report);
    }
    if let Err(e) = openwarrant_core::timestamp::validate_rfc3339_utc(&response.effective_time) {
        refuse(
            &mut report,
            "sas.effective-time",
            format!(
                "effective_time {:?} is not an RFC 3339 UTC timestamp ({e}); a record dated \
                 \"soon\" cannot be ordered against any other",
                response.effective_time
            ),
        );
        return Ok(report);
    }
    // The signature is over a digest; it must match the record AND the bytes on
    // disk right now. A document edited between proposal and acceptance is a
    // different document.
    let current = if record.source_set.is_some() {
        if let Err(e) = crate::sas_source_set::validate(repo, &record, true) {
            refuse(&mut report, "sas.stale-source-set", e.to_string());
            return Ok(report);
        }
        record.sha256.clone()
    } else {
        let (_, bytes) = repo.sas_document()?;
        sha256_hex(&bytes)
    };
    if response.sha256 != record.sha256 || current != record.sha256 {
        refuse(
            &mut report,
            "sas.stale-digest",
            format!(
                "response signs {}, record holds {}, document is now {current}. §101.6 is about the \
                 EXACT revision; re-propose and sign again",
                response.sha256, record.sha256
            ),
        );
        return Ok(report);
    }
    let register = repo.load_authority_register()?;
    let Some(assignment) = register.actor(&response.accepted_by) else {
        refuse(
            &mut report,
            "sas.unknown-actor",
            format!(
                "{:?} holds no role assignment in docs/authority/roles.toml",
                response.accepted_by
            ),
        );
        return Ok(report);
    };
    if let Err(e) = assignment.may_authorize(&repo.performer()) {
        refuse(&mut report, "sas.not-permitted", e.to_string());
        return Ok(report);
    }
    if let Some(subject) = &record.source_set {
        if response.acting_role != "authorizer"
            || response.adr_ref.as_deref() != Some(&subject.decision.path)
        {
            refuse(
                &mut report,
                "sas.response-subject",
                "response must name the authorizer role and captured adoption decision".into(),
            );
            return Ok(report);
        }
        let authenticated = match terminal_actor {
            Some(actor) if actor == response.accepted_by => Ok(()),
            Some(_) => Err("response actor differs from the terminal signer".into()),
            None => crate::sign::principal_of(repo, &response.accepted_by).and_then(|principal| {
                crate::sign::ssh_verify_bytes(
                    &crate::sign::allowed_signers_path(repo),
                    &principal,
                    response_path,
                    text.as_bytes(),
                )
            }),
        };
        if let Err(why) = authenticated {
            refuse(&mut report, "sas.response-signature", why);
            return Ok(report);
        }
    }
    // §101.3's ADR, named either way a person would name it: the path to the
    // atom, or the local alias the atom declares. An alias is what `war sign
    // --adr` is given and what the ADR calls itself, so resolving it here is
    // the difference between a refusal and a signature for the same intent.
    if let Some(adr) = &response.adr_ref
        && !repo.root.join(adr).is_file()
    {
        let known = repo.load_adrs().map(|a| a.records).unwrap_or_default();
        if !known.iter().any(|r| &r.local_alias == adr) {
            let aliases: Vec<&str> = known.iter().map(|r| r.local_alias.as_str()).collect();
            refuse(
                &mut report,
                "sas.adr-missing",
                format!(
                    "adr_ref {adr:?} is neither a file in this repository nor the local alias of a recorded ADR. Recorded: {}",
                    if aliases.is_empty() {
                        "none".to_owned()
                    } else {
                        aliases.join(", ")
                    }
                ),
            );
            return Ok(report);
        }
    }
    let accepted = record
        .clone()
        .accept(SasAcceptance {
            accepted_by: response.accepted_by.clone(),
            actor_kind: assignment.actor_kind,
            acting_role: response.acting_role.clone(),
            meaning: response.meaning.clone(),
            effective_time: response.effective_time.clone(),
            adr_ref: response.adr_ref.clone(),
        })
        .map_err(|e| RepoError::Message(e.to_string()))?;
    let out = repo.sas_revision_path(version);
    if record.source_set.is_some() {
        crate::sas_source_set::publish_acceptance(repo, &record, &accepted)?;
    } else {
        write_toml(&out, &accepted)?;
    }
    report.push(Diagnostic::pass(
        "sas.accepted",
        format!(
            "{version} accepted by {} acting as {} → {}",
            response.accepted_by,
            response.acting_role,
            repo.relative(&out)
        ),
    ));
    Ok(report)
}

/// §106 of the document as it stands versus a candidate document.
pub fn diff(repo: &Repository, candidate: &Utf8Path) -> Result<Report, RepoError> {
    let mut report = Report::default();
    let (_, bytes) = repo.sas_document()?;
    let current = section_106(&String::from_utf8_lossy(&bytes));
    let next_text = fs::read_to_string(candidate).map_err(|source| RepoError::Io {
        context: format!("could not read {candidate}"),
        source,
    })?;
    let next = section_106(&next_text);
    if next.is_empty() {
        report.push(Diagnostic::error(
            "sas.no-index",
            candidate.to_string(),
            "no §106 rows found; a candidate with no requirement index cannot be compared",
        ));
        return Ok(report);
    }
    let d = Section106Diff::between(&current, &next);
    for id in &d.added {
        report.push(Diagnostic::pass(
            "sas.diff.added",
            format!("{id}: {}", next[id]),
        ));
    }
    for (id, before, after) in &d.retitled {
        report.push(Diagnostic::warn(
            "sas.diff.retitled",
            candidate.to_string(),
            format!("{id}: {before:?} → {after:?} (architecture-changing; needs an ADR to accept)"),
        ));
    }
    for id in &d.removed {
        report.push(Diagnostic::error(
            "sas.diff.removed",
            candidate.to_string(),
            format!(
                "{id} — {}",
                openwarrant_core::sas::SasError::IdRemoved { id: id.clone() }
            ),
        ));
    }
    if !d.is_architecture_changing() {
        report.push(Diagnostic::pass("sas.diff", "§106 unchanged".to_owned()));
    }
    report.note(format!(
        "{}; architecture-changing: {}",
        d.summary(),
        d.is_architecture_changing()
    ));
    Ok(report)
}

/// Every revision on record, and which one the document currently matches.
pub fn status(repo: &Repository) -> Result<Report, RepoError> {
    let mut report = Report::default();
    let revisions = repo.load_sas_revisions()?;
    if revisions.iter().any(|r| r.source_set.is_some()) {
        for r in &revisions {
            if r.source_set.is_some() {
                source_set_status(repo, r, &mut report);
            } else {
                let (_, bytes) = repo.sas_document()?;
                let matches = sha256_hex(&bytes) == r.sha256;
                let line = format!(
                    "{} · {} · sha256:{} · {} the legacy document",
                    r.version,
                    r.state,
                    &r.sha256[..12],
                    if matches { "matches" } else { "does not match" }
                );
                if matches {
                    report.push(Diagnostic::pass("sas.revision", line));
                } else {
                    report.push(Diagnostic::warn("sas.revision", r.source.clone(), line));
                }
            }
        }
        return Ok(report);
    }
    let (path, bytes) = repo.sas_document()?;
    let current = sha256_hex(&bytes);
    if revisions.is_empty() {
        report.push(Diagnostic::warn(
            "sas.unrecorded",
            repo.relative(&path),
            format!(
                "no revision is recorded; the document is at sha256:{current} and nothing pins it"
            ),
        ));
        return Ok(report);
    }
    for r in &revisions {
        let line = format!("{} · {} · sha256:{}", r.version, r.state, &r.sha256[..12]);
        if r.sha256 == current {
            report.push(Diagnostic::pass(
                "sas.revision",
                format!("{line} · matches the document"),
            ));
        } else {
            // A recorded revision the document no longer matches is worth a
            // reader's attention even when a newer one does match it.
            report.push(Diagnostic::warn(
                "sas.revision",
                repo.relative(&path),
                format!("{line} · does not match the document"),
            ));
        }
    }
    Ok(report)
}

pub(crate) fn source_set_status(repo: &Repository, r: &SasRevision, report: &mut Report) {
    match crate::sas_source_set::validate(repo, r, false) {
        Err(e) => report.push(Diagnostic::error(
            "sas.capture-invalid",
            r.source.clone(),
            e.to_string(),
        )),
        Ok(()) => {
            report.push(Diagnostic::pass(
                "sas.capture-intact",
                format!(
                    "{} · {} · complete subject sha256:{} · retained capture intact",
                    r.version, r.state, r.sha256
                ),
            ));
            match crate::sas_source_set::validate(repo, r, true) {
                Ok(()) => report.push(Diagnostic::pass(
                    "sas.current-matches",
                    format!("{}: current inputs match captured subject", r.version),
                )),
                Err(e) => report.push(Diagnostic::warn(
                    "sas.current-differs",
                    r.source.clone(),
                    format!(
                        "{}: current inputs differ; historical capture remains intact: {e}",
                        r.version
                    ),
                )),
            }
        }
    }
}

fn find(repo: &Repository, version: &str) -> Result<SasRevision, RepoError> {
    repo.load_sas_revisions()?
        .into_iter()
        .find(|r| r.version == version)
        .ok_or_else(|| RepoError::Message(format!("no SAS revision named {version:?}")))
}

fn write_toml<T: Serialize>(path: &Utf8Path, value: &T) -> Result<(), RepoError> {
    let rendered = toml::to_string_pretty(value).map_err(|e| RepoError::Message(e.to_string()))?;
    fs::write(path, rendered).map_err(|source| RepoError::Io {
        context: format!("could not write {path}"),
        source,
    })
}

/// Which revision the document is currently held to: the newest accepted, else
/// the newest proposed. `None` when nothing is recorded.
#[must_use]
pub fn pin_of(revisions: &[SasRevision]) -> Option<&SasRevision> {
    revisions
        .iter()
        .filter(|r| r.state == SasRevisionState::Accepted)
        .max_by(|a, b| a.version.cmp(&b.version))
        .or_else(|| revisions.iter().max_by(|a, b| a.version.cmp(&b.version)))
}

