        let next = rows(&[("WAR-SAS-RQ-001", "a2"), ("WAR-SAS-RQ-003", "c")]);
        let d = Section106Diff::between(&prev, &next);
        assert_eq!(d.added, vec!["WAR-SAS-RQ-003"]);
